//! SSH tunnel integration tests (M3-1 / US-02).
//!
//! Skipped unless `SELA_SSH_HOST` is set — same pattern as `SELA_POSTGRES_URL` /
//! `postgres_tls`. Once `SELA_SSH_HOST` is set, missing required vars fail the
//! test (fail-not-skip). `SELA_SSH_REQUIRED=1` (CI) also fails if HOST is unset.
//! Keys and known_hosts are generated by `scripts/run-ssh-bastion.sh` at
//! runtime; never committed.
//!
//! Test names include the QA plan ids from `docs/qa/v0.3-test-plan.md`.

use std::path::PathBuf;
use std::sync::{Arc, OnceLock};
use std::time::Duration;

use sela_core::{
    DbError, Engine, SavedConnection, SshAuthMethod, SshSettings, TlsMode, TlsSettings,
};
use sela_drivers::{connect_with_auth, ConnectAuth, ConnectOutcome, SshAuthSecrets, SshPaths};
use sela_ssh::{open_tunnel, TunnelOpen, TunnelRequest};
use tokio::sync::{OwnedSemaphorePermit, Semaphore};

/// Cap concurrent handshakes against the bastion so a default OpenSSH
/// `MaxStartups 10:30:100` does not randomly drop unauthenticated connects
/// when `cargo test` runs the suite in parallel.
fn bastion_slots() -> Arc<Semaphore> {
    static SLOTS: OnceLock<Arc<Semaphore>> = OnceLock::new();
    SLOTS.get_or_init(|| Arc::new(Semaphore::new(4))).clone()
}

async fn acquire_bastion_slot() -> OwnedSemaphorePermit {
    bastion_slots()
        .acquire_owned()
        .await
        .expect("bastion concurrency semaphore closed")
}

struct SshEnv {
    host: String,
    port: u16,
    user: String,
    password: String,
    key: PathBuf,
    key_encrypted: PathBuf,
    key_passphrase: String,
    known_hosts: PathBuf,
    known_hosts_bad: PathBuf,
    db_host: String,
    db_port: u16,
    db_user: String,
    db_password: String,
    db_name: String,
    mysql_host: Option<String>,
    mysql_port: Option<u16>,
    home: PathBuf,
}

fn require_ssh_var(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| {
        panic!(
            "SELA_SSH_HOST is set but {name} is missing — refusing to skip SSH tests (fail-not-skip)"
        )
    })
}

fn ssh_required() -> bool {
    std::env::var("SELA_SSH_REQUIRED").ok().as_deref() == Some("1")
}

fn ssh_env() -> Option<SshEnv> {
    // Unset HOST → skip locally. SELA_SSH_REQUIRED=1 (CI) makes missing HOST a failure.
    let host = match std::env::var("SELA_SSH_HOST") {
        Ok(h) if !h.is_empty() => h,
        _ => {
            if ssh_required() {
                panic!(
                    "SELA_SSH_REQUIRED=1 but SELA_SSH_HOST is unset — SSH integration env is required"
                );
            }
            return None;
        }
    };

    // Once HOST is set, incomplete env must fail (not skip).
    let port: u16 = require_ssh_var("SELA_SSH_PORT")
        .parse()
        .expect("SELA_SSH_PORT must be a u16");
    let user = require_ssh_var("SELA_SSH_USER");
    let password = require_ssh_var("SELA_SSH_PASSWORD");
    let key = PathBuf::from(require_ssh_var("SELA_SSH_KEY"));
    let key_encrypted = PathBuf::from(require_ssh_var("SELA_SSH_KEY_ENCRYPTED"));
    let key_passphrase = require_ssh_var("SELA_SSH_KEY_PASSPHRASE");
    let known_hosts = PathBuf::from(require_ssh_var("SELA_SSH_KNOWN_HOSTS"));
    let known_hosts_bad = PathBuf::from(require_ssh_var("SELA_SSH_KNOWN_HOSTS_BAD"));
    let db_host = require_ssh_var("SELA_SSH_DB_HOST");
    let db_port: u16 = std::env::var("SELA_SSH_DB_PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(5432);
    let db_user = std::env::var("SELA_SSH_DB_USER").unwrap_or_else(|_| "sela".into());
    let db_password = std::env::var("SELA_SSH_DB_PASSWORD").unwrap_or_else(|_| "sela".into());
    let db_name = std::env::var("SELA_SSH_DB_NAME").unwrap_or_else(|_| "sample".into());
    let mysql_host = std::env::var("SELA_SSH_MYSQL_HOST").ok();
    let mysql_port = std::env::var("SELA_SSH_MYSQL_PORT")
        .ok()
        .and_then(|p| p.parse().ok());
    let home = known_hosts
        .parent()
        .and_then(|p| p.parent())
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| PathBuf::from("."));
    Some(SshEnv {
        host,
        port,
        user,
        password,
        key,
        key_encrypted,
        key_passphrase,
        known_hosts,
        known_hosts_bad,
        db_host,
        db_port,
        db_user,
        db_password,
        db_name,
        mysql_host,
        mysql_port,
        home,
    })
}

fn paths(env: &SshEnv) -> SshPaths {
    SshPaths::from_home(&env.home)
        .with_known_hosts(env.known_hosts.clone())
        .without_config()
}

fn pg_connection(env: &SshEnv, ssh: SshSettings) -> SavedConnection {
    let mut c = SavedConnection::new(Engine::Postgres);
    c.name = "ssh-ci".into();
    c.host = env.db_host.clone();
    c.port = env.db_port;
    c.username = env.db_user.clone();
    c.database = env.db_name.clone();
    c.tls = TlsSettings {
        mode: TlsMode::Disable,
        ..TlsSettings::default()
    };
    c.ssh = ssh;
    c
}

fn password_ssh(env: &SshEnv) -> SshSettings {
    SshSettings {
        enabled: true,
        host: env.host.clone(),
        port: env.port,
        user: env.user.clone(),
        auth: SshAuthMethod::Password,
        private_key_path: String::new(),
    }
}

fn key_ssh(env: &SshEnv, encrypted: bool) -> SshSettings {
    SshSettings {
        enabled: true,
        host: env.host.clone(),
        port: env.port,
        user: env.user.clone(),
        auth: SshAuthMethod::PrivateKey,
        private_key_path: if encrypted {
            env.key_encrypted.display().to_string()
        } else {
            env.key.display().to_string()
        },
    }
}

fn auth_password(env: &SshEnv) -> ConnectAuth {
    ConnectAuth {
        db_password: env.db_password.clone(),
        ssh: SshAuthSecrets {
            password: Some(env.password.clone()),
            passphrase: None,
        },
        ssh_paths: Some(paths(env)),
    }
}

fn auth_key(env: &SshEnv, passphrase: Option<String>) -> ConnectAuth {
    ConnectAuth {
        db_password: env.db_password.clone(),
        ssh: SshAuthSecrets {
            password: None,
            passphrase,
        },
        ssh_paths: Some(paths(env)),
    }
}

async fn assert_select_one(session: &dyn sela_core::DatabaseSession) {
    let page = session.query("SELECT 1 AS n").await.expect("SELECT 1");
    assert!(!page.rows.is_empty(), "expected a row through the tunnel");
}

#[tokio::test]
async fn ssh01_password_auth_then_postgres_query() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let _bastion = acquire_bastion_slot().await;
    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("SSH password connect");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready with known_hosts present");
    };
    assert_select_one(session.as_ref()).await;
}

