#[tokio::test]
async fn ssh18_unknown_host_key_challenge_then_accept() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let _bastion = acquire_bastion_slot().await;
    let empty_known = env.home.join(".ssh").join("known_hosts.empty");
    let _ = std::fs::remove_file(&empty_known);
    std::fs::File::create(&empty_known).unwrap();
    let mut paths = paths(&env);
    paths.known_hosts = empty_known.clone();

    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(
        &conn,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets {
                password: Some(env.password.clone()),
                passphrase: None,
            },
            ssh_paths: Some(paths),
        },
    )
    .await
    .expect("unknown host returns outcome");
    let ConnectOutcome::UnknownSshHostKey(challenge) = outcome else {
        panic!("expected UnknownSshHostKey challenge");
    };
    assert!(
        challenge.fingerprint.starts_with("SHA256:"),
        "fingerprint={}",
        challenge.fingerprint
    );
    // Reject path (typed error); known_hosts must stay empty.
    let rejected = challenge.reject();
    assert!(matches!(rejected, DbError::Ssh { .. }));
    let after_reject = std::fs::read_to_string(&empty_known).unwrap_or_default();
    assert!(
        after_reject.trim().is_empty(),
        "reject must not write known_hosts; got {after_reject:?}"
    );

    // Fresh challenge → accept_and_remember.
    let paths = SshPaths::from_home(&env.home)
        .with_known_hosts(empty_known.clone())
        .without_config();
    let outcome = connect_with_auth(
        &conn,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets {
                password: Some(env.password.clone()),
                passphrase: None,
            },
            ssh_paths: Some(paths),
        },
    )
    .await
    .expect("second unknown");
    let ConnectOutcome::UnknownSshHostKey(challenge) = outcome else {
        panic!("expected challenge again");
    };
    let session = (*challenge)
        .accept_and_remember()
        .await
        .expect("accept_and_remember");
    assert_select_one(session.as_ref()).await;
    let written = std::fs::read_to_string(&empty_known).unwrap();
    assert!(
        written.contains(&env.host) || written.contains(&format!("[{}]:{}", env.host, env.port)),
        "known_hosts should record the host after accept"
    );

    // Changed key remains a hard error (no override) — covered by ssh07.
    let _ = Duration::from_secs(0);
}

/// SSH-11: drop the SSH forward while `pg_sleep` is in flight; query must error
/// (no hang / panic). Holds the tunnel handle separately from the DB session.
#[tokio::test]
async fn ssh11_tunnel_drop_while_pg_sleep_surfaces_error() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let _bastion = acquire_bastion_slot().await;
    let request = TunnelRequest {
        ssh: password_ssh(&env),
        remote_db_host: env.db_host.clone(),
        remote_db_port: env.db_port,
        secrets: SshAuthSecrets {
            password: Some(env.password.clone()),
            passphrase: None,
        },
        paths: paths(&env),
    };
    let TunnelOpen::Ready(tunnel) = open_tunnel(request).await.expect("open tunnel") else {
        panic!("expected Ready");
    };
    let local = tunnel.local_addr();
    // Dial the ephemeral listener with SSH off so we can close the tunnel
    // independently while the query runs.
    let mut dial = pg_connection(
        &env,
        SshSettings {
            enabled: false,
            ..SshSettings::default()
        },
    );
    dial.host = "127.0.0.1".into();
    dial.port = local.port();
    let outcome = connect_with_auth(
        &dial,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets::default(),
            ssh_paths: None,
        },
    )
    .await
    .expect("dial through tunnel");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready");
    };

    let query = tokio::spawn(async move {
        session
            .query("SELECT pg_sleep(5)")
            .await
            .map(|_| ())
            .map_err(|err| err.to_string())
    });
    // Let the sleep start on the server, then tear down the SSH forward.
    tokio::time::sleep(Duration::from_millis(400)).await;
    tunnel.close().await;

    let result = tokio::time::timeout(Duration::from_secs(15), query)
        .await
        .expect("pg_sleep must not hang after tunnel drop")
        .expect("query task join");
    assert!(
        result.is_err(),
        "SSH-11: query during tunnel drop must return an error, got Ok"
    );

    // A fresh tunneled connect still works (reconnect required after drop).
    let again = connect_with_auth(
        &pg_connection(&env, password_ssh(&env)),
        auth_password(&env),
    )
    .await
    .expect("reconnect after mid-query drop");
    assert!(matches!(again, ConnectOutcome::Ready(_)));
}

